def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    opp = [h[1] for h in history]
    me = [h[0] for h in history]

    opp_c = sum(1 for a in opp if a == 'C')
    opp_d = n - opp_c

    # Early: cooperate to establish mutual cooperation.
    if n < 5:
        return 'C'

    # Count recent opponent cooperation over last 10.
    window = opp[-10:] if n >= 10 else opp
    w_c = sum(1 for a in window if a == 'C')
    w_d = len(window) - w_c

    # Count consecutive opponent defections at the end.
    consec_d = 0
    for a in reversed(opp):
        if a == 'D':
            consec_d += 1
        else:
            break

    # Consecutive opponent cooperations at end.
    consec_c = 0
    for a in reversed(opp):
        if a == 'C':
            consec_c += 1
        else:
            break

    last_opp = opp[-1]
    last_me = me[-1]

    # Detect pure/all-defect opponent: never cooperate meaningfully.
    if opp_c == 0:
        return 'D'
    if n >= 12 and opp_c <= 1:
        return 'D'

    # Endgame: secure mutual cooperation, but punish recent defections.
    remaining = 100 - n
    if remaining <= 3:
        if last_opp == 'C' and consec_d == 0:
            return 'D' if opp_d == 0 else 'C'
        return 'D'

    # Mostly cooperative opponents: keep cooperation, avoid greedy probing
    # because TFT-like opponents punish and recovery is expensive.
    if w_d <= 1 and opp_d * 4 <= n:
        return 'C'

    # Opponent heavily defecting: defect, with rare probes.
    if w_d >= 6 or (n >= 15 and opp_d * 3 >= n * 2):
        if consec_d >= 5 and n % 13 == 0:
            return 'C'
        return 'D'

    # Opponent just defected.
    if last_opp == 'D':
        # If overall mostly cooperative, retaliate on the immediate round
        # but prepare to forgive quickly.
        if opp_d * 3 <= n:
            return 'D'
        # If recent window shows mostly cooperation, retaliate once.
        if w_d <= 1:
            return 'D'
        # Long defection streak: mostly defect, occasional cooperation to test.
        if consec_d >= 4:
            if consec_d >= 8 and rng.random() < 0.2:
                return 'C'
            return 'D'
        # Moderate defection: retaliate, but forgive after isolated defects.
        if consec_d == 1 and w_c >= 7:
            return 'D'
        if consec_d >= 2:
            if rng.random() < 0.25:
                return 'C'
            return 'D'
        return 'D'

    # Opponent cooperated last.
    # If we defected last and opponent still cooperated, return to cooperation
    # to reward forgiveness and sustain mutual CC.
    if last_me == 'D':
        return 'C'

    # Opponent cooperated and we cooperated. Check for sustained cooperation.
    if consec_c >= 3:
        # Do not probe often; TFT opponents punish probes hard.
        if remaining > 20 and n % 17 == 0 and opp_d * 5 <= n:
            return 'D'
        return 'C'

    # Recent opponent mixed: cooperate if cooperation dominates.
    if w_c >= 7:
        return 'C'

    # Default: cooperate to encourage mutual cooperation.
    return 'C'
